package com.codiebutterfly.schoolrun;

import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.transaction.support.TransactionTemplate;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static com.codiebutterfly.schoolrun.Store.*;

@RestController @RequestMapping("/api") public class Billing {
 final Store s; final PaynowClient pay; final TransactionTemplate tx;
 final BigDecimal price; final String currency,unit;
 Billing(Store s,PaynowClient pay,TransactionTemplate tx,@Value("${schoolrun.subscription-price}")BigDecimal price,@Value("${schoolrun.currency}")String currency,@Value("${schoolrun.subscription-unit}")String unit){this.s=s;this.pay=pay;this.tx=tx;this.price=unit.equals("CHILD")?BigDecimal.ONE:price;this.currency=currency;this.unit=unit;}
 String month(String value){try{YearMonth m=YearMonth.parse(value);if(m.isBefore(YearMonth.of(2026,10))||m.isAfter(YearMonth.now(ZONE).plusMonths(1)))throw error(400,"Choose this month or next month");return m.toString();}catch(java.time.format.DateTimeParseException e){throw error(400,"Use YYYY-MM");}}
 @GetMapping("/subscriptions") @org.springframework.transaction.annotation.Transactional Object subscriptions(@RequestHeader(value="Authorization",required=false)String a,@RequestParam String month){var u=s.user(a);String m=month(month);var rows=s.db.queryForList("SELECT l.id,p.name parent_name,d.name driver_name FROM sr_link l JOIN sr_user p ON p.id=l.parent_id JOIN sr_user d ON d.id=l.driver_id WHERE l.parent_id=? OR l.driver_id=?",u.get("id"),u.get("id"));for(var r:rows){if(unit.equals("CHILD")){s.one("SELECT id FROM sr_link WHERE id=? FOR UPDATE",r.get("id"));s.accrue(r.get("id"));}r.put("paid",s.paid(r.get("id"),m));r.put("enabled",s.serviceEnabled(r.get("id")));r.put("childCount",s.db.queryForObject("SELECT count(*) FROM sr_child WHERE link_id=?",Integer.class,r.get("id")));r.put("amountDue",s.db.queryForObject("SELECT coalesce(sum(q.amount),0) FROM sr_child_charge q JOIN sr_child c ON c.id=q.child_id WHERE c.link_id=? AND q.billing_month=? AND q.paid=false",BigDecimal.class,r.get("id"),m));r.put("totalOutstanding",s.db.queryForObject("SELECT coalesce(sum(q.amount),0) FROM sr_child_charge q JOIN sr_child c ON c.id=q.child_id WHERE c.link_id=? AND q.paid=false",BigDecimal.class,r.get("id")));r.put("charges",s.db.queryForList("SELECT q.billing_month,q.amount,q.paid,c.details FROM sr_child_charge q JOIN sr_child c ON c.id=q.child_id WHERE c.link_id=? ORDER BY q.billing_month DESC",r.get("id")).stream().map(q->{Map<String,Object>d=s.decode(q.remove("details"));q.put("childName",d.get("name"));return q;}).toList());}return Map.of("month",m,"unit",unit,"price",price,"currency",currency,"customers",rows,"configured",price.signum()>0&&Set.of("CUSTOMER","CHILD").contains(unit));}
 @PostMapping("/payments") Object initiate(@RequestHeader(value="Authorization",required=false)String a,@RequestBody Map<String,Object>b){
  var u=s.user(a);s.role(u,"DRIVER");pay.requireConfigured();pay.allowDriver(u.get("id").toString());if(price.signum()<=0||!Set.of("CUSTOMER","CHILD").contains(unit)||!currency.equals("USD"))throw error(503,"Subscription pricing is awaiting configuration");
  String key=text(b,"idempotencyKey",100),m=month(text(b,"month",7));String method=PaynowClient.validateMethod((String)b.getOrDefault("method","browser"));String phone=(String)b.get("phone");pay.validateCheckout(method,phone,u.get("email").toString());
  if(!(b.get("linkIds") instanceof List<?> list)||list.isEmpty()||list.size()>200)throw error(400,"Select customers to cover");var selected=list.stream().map(Object::toString).distinct().sorted().toList();
  var payment=tx.execute(status->{s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",u.get("id"));var old=s.db.queryForList("SELECT * FROM sr_payment WHERE driver_id=? AND idempotency_key=?",u.get("id"),key);if(!old.isEmpty()){var p=old.get(0);if(!p.get("selection").equals(s.encode(selected))||!p.get("billing_month").equals(m))throw error(409,"This payment key was used for a different selection");return p;}
   BigDecimal chargeTotal=BigDecimal.ZERO;for(String link:selected){s.one("SELECT id FROM sr_link WHERE id=? AND driver_id=?",link,u.get("id"));if(unit.equals("CHILD"))s.accrue(link);if(s.paid(link,m))throw error(409,"A selected customer is already covered");if(unit.equals("CHILD")){BigDecimal due=s.db.queryForObject("SELECT coalesce(sum(q.amount),0) FROM sr_child_charge q JOIN sr_child c ON c.id=q.child_id WHERE c.link_id=? AND q.billing_month=? AND q.paid=false",BigDecimal.class,link,m);if(due.signum()==0)throw error(409,"No child charges due for a selected family");chargeTotal=chargeTotal.add(due);}}
   for(var p:s.db.queryForList("SELECT selection FROM sr_payment WHERE driver_id=? AND billing_month=? AND state IN ('INITIATING','PENDING','UNKNOWN')",u.get("id"),m)){List<String> reserved=s.decode(p.get("selection"));if(reserved.stream().anyMatch(selected::contains))throw error(409,"A payment for this customer needs checking before another attempt");}
   String id=id();s.db.update("INSERT INTO sr_payment(id,driver_id,billing_month,amount,currency,selection,state,idempotency_key) VALUES(?,?,?,?,?,?,?,?)",id,u.get("id"),m,unit.equals("CHILD")?chargeTotal:price.multiply(BigDecimal.valueOf(selected.size())),currency,s.encode(selected),"INITIATING",key);if(unit.equals("CHILD"))for(String link:selected)s.db.update("UPDATE sr_child_charge SET payment_id=? WHERE billing_month=? AND paid=false AND child_id IN(SELECT id FROM sr_child WHERE link_id=?)",id,m,link);var p=s.one("SELECT * FROM sr_payment WHERE id=?",id);p.put("new",true);return p;});
  if(!Boolean.TRUE.equals(payment.remove("new")))return publicPayment(payment);
  String id=payment.get("id").toString();
  try{var r=pay.initiate(id,payment.get("amount").toString(),method,phone,u.get("email").toString());s.db.update("UPDATE sr_payment SET state='PENDING',poll_url=?,browser_url=? WHERE id=?",r.get("pollurl"),r.get("browserurl"),id);}
  catch(PaynowClient.InitiationRejected e){s.db.update("UPDATE sr_payment SET state='FAILED' WHERE id=?",id);throw e;}
  catch(RuntimeException e){s.db.update("UPDATE sr_payment SET state='UNKNOWN' WHERE id=?",id);throw error(502,"Payment outcome is uncertain. Do not pay again; contact support with reference "+id);}
  return publicPayment(s.one("SELECT * FROM sr_payment WHERE id=?",id));
 }
 Map<String,Object> publicPayment(Map<String,Object>p){var out=new LinkedHashMap<String,Object>();for(String k:List.of("id","billing_month","amount","currency","state","browser_url","created_at"))out.put(k,p.get(k));return out;}
 @GetMapping("/payments") Object history(@RequestHeader(value="Authorization",required=false)String a){var u=s.user(a);s.role(u,"DRIVER");return s.db.queryForList("SELECT * FROM sr_payment WHERE driver_id=? ORDER BY created_at DESC LIMIT 100",u.get("id")).stream().map(this::publicPayment).toList();}
 @PostMapping("/payments/{id}/check") Object check(@RequestHeader(value="Authorization",required=false)String a,@PathVariable String id){var u=s.user(a);s.role(u,"DRIVER");var p=s.one("SELECT * FROM sr_payment WHERE id=? AND driver_id=?",id,u.get("id"));return reconcile(p);}
 Object reconcile(Map<String,Object>p){if(p.get("state").equals("PAID")||p.get("state").equals("FAILED"))return publicPayment(p);if(p.get("poll_url")==null)return publicPayment(p);var r=pay.poll(p.get("poll_url").toString());if(!p.get("id").equals(r.get("reference")))throw error(502,"Payment reference mismatch");try{if(new BigDecimal(r.get("amount")).compareTo(new BigDecimal(p.get("amount").toString()))!=0)throw error(502,"Payment amount mismatch");}catch(NumberFormatException|NullPointerException e){throw error(502,"Invalid payment amount");}
  return tx.execute(status->{s.one("SELECT id FROM sr_user WHERE id=? FOR UPDATE",p.get("driver_id"));var current=s.one("SELECT * FROM sr_payment WHERE id=?",p.get("id"));if(current.get("state").equals("PAID"))return publicPayment(current);String gateway=r.getOrDefault("status","").toLowerCase(Locale.ROOT);String state=Set.of("paid","awaiting delivery","delivered").contains(gateway)?"PAID":Set.of("cancelled","failed").contains(gateway)?"FAILED":"PENDING";s.db.update("UPDATE sr_payment SET state=? WHERE id=?",state,p.get("id"));if(state.equals("PAID")){s.db.update("UPDATE sr_child_charge SET paid=true WHERE payment_id=?",p.get("id"));List<String> links=s.decode(p.get("selection"));for(String link:links){if(s.db.queryForObject("SELECT count(*) FROM sr_entitlement WHERE link_id=? AND billing_month=?",Integer.class,link,p.get("billing_month"))==0)s.db.update("INSERT INTO sr_entitlement VALUES(?,?,?)",link,p.get("billing_month"),p.get("id"));var l=s.one("SELECT parent_id FROM sr_link WHERE id=?",link);s.notifyUser(l.get("parent_id"),"Subscription active","A platform subscription payment was verified for "+p.get("billing_month")+". Check Subscriptions for any outstanding child charges.",null);}}return publicPayment(s.one("SELECT * FROM sr_payment WHERE id=?",p.get("id")));});
 }
 @PostMapping(value="/paynow/result",consumes="application/x-www-form-urlencoded") Object callback(@RequestBody String body){var r=PaynowClient.parse(body);pay.verify(r);var p=s.one("SELECT * FROM sr_payment WHERE id=?",r.get("reference"));reconcile(p);return Map.of("received",true);}
 @GetMapping(value="/paynow/return",produces="text/plain") String returned(){return "Return to School Run and tap Check payment. Coverage is enabled only after the payment is verified.";}
}
